import logging
from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

from aie_lab.core.errors import DataFetchError, DataParseError

logger = logging.getLogger(__name__)

def envelope(status: int, code: str, message: str,
             request_id: str) -> JSONResponse:
    return JSONResponse(
        status_code=status,
        content={'error': {'code': code, 'message': message,
                           'request_id': request_id}},
    )

def rid(request: Request) -> str:
    return getattr(request.state, 'request_id', 'unknown')

@app.exception_handler(DataFetchError)
async def handle_fetch(request: Request,
                       exc: DataFetchError) -> JSONResponse:
    logger.exception('upstream fetch failed')
    return envelope(502, 'upstream_unavailable',
                    'upstream service unavailable', rid(request))

@app.exception_handler(RequestValidationError)
async def handle_validation(
        request: Request,
        exc: RequestValidationError) -> JSONResponse:
    first = exc.errors()[0]
    field = '.'.join(str(p) for p in first['loc'][1:])
    return envelope(422, 'validation_error',
                    field + ': ' + first['msg'], rid(request))

@app.exception_handler(Exception)
async def handle_unexpected(request: Request,
                            exc: Exception) -> JSONResponse:
    logger.exception('unhandled error')
    return envelope(500, 'internal_error',
                    'internal error', rid(request))

import secrets
from dataclasses import dataclass
from typing import Annotated

from fastapi import Depends, HTTPException, Security
from fastapi.security import APIKeyHeader

api_key_header = APIKeyHeader(name='X-API-Key',
                              auto_error=False)

@dataclass(frozen=True)
class Principal:
    name: str
    scopes: frozenset[str]

def require_api_key(
    settings: SettingsDep,
    presented: Annotated[str | None, Security(api_key_header)],
) -> Principal:
    if presented is None:
        raise HTTPException(401, detail='unauthenticated')
    for name, record in settings.api_keys.items():
        if secrets.compare_digest(presented, record['key']):
            return Principal(name, frozenset(record['scopes']))
    raise HTTPException(401, detail='invalid_key')

PrincipalDep = Annotated[Principal, Depends(require_api_key)]

def require_scope(scope: str):
    def checker(principal: PrincipalDep) -> Principal:
        if scope not in principal.scopes:
            raise HTTPException(403, detail='forbidden')
        return principal
    return checker

