@dataclass
class Record:
    request_hash: str
    status: int
    body: dict
    created_at: float

class IdempotencyStore:
    TTL_S = 24 * 60 * 60

    def __init__(self) -> None:
        self._items: dict[str, Record] = {}

    def _sweep(self) -> None:
        cutoff = time.time() - self.TTL_S
        for key in [k for k, r in self._items.items()
                    if r.created_at < cutoff]:
            del self._items[key]

    def get(self, key: str) -> Record | None:
        self._sweep()
        return self._items.get(key)

    def put(self, key: str, request_hash: str,
            status: int, body: dict) -> None:
        self._items[key] = Record(request_hash, status, body,
                                  time.time())

def body_hash(payload: dict) -> str:
    canonical = json.dumps(payload, sort_keys=True,
                           separators=(',', ':'))
    return hashlib.sha256(canonical.encode()).hexdigest()

