from dataclasses import dataclass, field
from typing import Callable

@dataclass
class HistoryManager:
  budget: int
  count: Callable[[str], int]          # tokens(text) - fake in tests
  summarize: Callable[[list[str]], str]  # old turns -> summary text
  keep_recent: int = 6                 # keep even, to trim in pairs
  summary: str = ''
  turns: list[dict] = field(default_factory=list)

  def add(self, role: str, content: str) -> None:
    self.turns.append({'role': role, 'content': content})
    while self._tokens() > self.budget and len(self.turns) > self.keep_recent:
      old = self.turns[: -self.keep_recent]
      texts = ([self.summary] if self.summary else [])
      texts += [t['content'] for t in old]
      self.summary = self.summarize(texts)   # ONE slot, overwritten
      self.turns = self.turns[-self.keep_recent:]

  def _tokens(self) -> int:
    total = self.count(self.summary) if self.summary else 0
    return total + sum(self.count(t['content']) for t in self.turns)

  def render(self) -> list[dict]:
    if not self.summary:
      return list(self.turns)
    pre = {'role': 'user',
           'content': 'Context - conversation so far: ' + self.summary}
    return [pre] + list(self.turns)

import datetime

def norm(field: str, val):
  if val is None:
    return None
  if field == 'currency':
    return str(val).upper()
  if field == 'date':
    return datetime.date.fromisoformat(str(val).strip())
  if field == 'participants':
    return frozenset(str(p).lower() for p in val)
  if field == 'amount':
    return round(float(val), 2)
  return str(val).strip().lower()

