from pydantic import BaseModel, ValidationError, Field

PRICE_IN = 3.0 / 1e6
PRICE_OUT = 15.0 / 1e6

class CostMeter:
  def __init__(self, cap_gbp=0.50):
    self.cap = cap_gbp
    self.tin = 0
    self.tout = 0
  def add(self, usage):
    self.tin += usage.input_tokens        # the big one: whole transcript
    self.tout += usage.output_tokens
  def spent(self):
    return self.tin * PRICE_IN + self.tout * PRICE_OUT
  def would_exceed(self, est_in=6000, est_out=1000):
    projected = self.spent() + est_in * PRICE_IN + est_out * PRICE_OUT
    return projected > self.cap           # checked BEFORE the next call

