import time, random

class CircuitOpen(Exception): pass

class CircuitBreaker:
    def __init__(self, threshold=5, cooldown=30.0):
        self.threshold, self.cooldown = threshold, cooldown
        self.failures = 0
        self.state = 'closed'
        self.opened_at = 0.0

    def _can_try(self):
        if self.state == 'open':
            if time.monotonic() - self.opened_at >= self.cooldown:
                self.state = 'half_open'   # allow one probe
                return True
            return False
        return True

    def call(self, fn, *a, **kw):
        if not self._can_try():
            raise CircuitOpen('breaker open')
        try:
            out = fn(*a, **kw)
        except Exception:
            self.failures += 1
            if self.state == 'half_open' or self.failures >= self.threshold:
                self.state, self.opened_at = 'open', time.monotonic()
            raise
        # success
        self.failures = 0
        self.state = 'closed'
        return out

